"#,
        )
        .unwrap();

        let config = load_for_run(temp.path(), "ci").unwrap();
        let workflow = config.workflows.get("ci").unwrap();
        assert_eq!(workflow.description, Some("Legacy CI".to_string()));
        assert_eq!(workflow.steps, vec!["deps"]);
