/// Known field names for step configurations (flattened from all sub-structs).
const KNOWN_STEP_FIELDS: &[&str] = &[
    // StepConfig direct fields
    "template",
    "inputs",
    "title",
    "description",
    "depends_on",
    "tools",
    "requires",
