/// Validate a raw YAML value for unknown fields that serde would silently ignore.
///
/// Returns errors for any unrecognized keys in `settings` or step definitions.
/// This catches typos and invalid field names that would otherwise cause a
/// silent fallback to default values.
pub fn validate_unknown_fields(raw: &serde_yaml::Value) -> Vec<ValidationError> {
    let mut errors = Vec::new();

    let Some(root) = raw.as_mapping() else {
        return errors;
    };

    if let Some(settings_val) = root.get(serde_yaml::Value::String("settings".to_string())) {
        if let Some(settings_map) = settings_val.as_mapping() {
            for key in settings_map.keys() {
                if let Some(key_str) = key.as_str() {
                    if !KNOWN_SETTINGS_FIELDS.contains(&key_str) {
                        errors.push(ValidationError {
                            rule: "unknown-field".to_string(),
                            message: format!(
                                "Unknown field '{}' in settings. Check for typos.",
                                key_str
                            ),
                            step: None,
                            workflow: None,
                        });
                    }
                }
            }
        }
    }

    if let Some(steps_val) = root.get(serde_yaml::Value::String("steps".to_string())) {
        if let Some(steps_map) = steps_val.as_mapping() {
            for (step_key, step_val) in steps_map {
                let step_name = step_key.as_str().unwrap_or("<unknown>");
                if let Some(step_map) = step_val.as_mapping() {
                    for key in step_map.keys() {
                        if let Some(key_str) = key.as_str() {
                            if !KNOWN_STEP_FIELDS.contains(&key_str) {
                                errors.push(ValidationError {
                                    rule: "unknown-field".to_string(),
                                    message: format!(
                                        "Unknown field '{}' in step '{}'. Check for typos.",
                                        key_str, step_name
                                    ),
                                    step: Some(step_name.to_string()),
                                    workflow: None,
                                });
                            }
                        }
                    }
                }
            }
        }
    }

    errors
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::schema::{
        ExecutionConfig, StepConfig, StepOverride, VarDefinition, WorkflowConfig,
    };

    #[test]
    fn validates_step_has_command_or_template() {
        let mut config = BivvyConfig::default();
        config
            .steps
            .insert("empty".to_string(), StepConfig::default());

        let errors = validate_config(&config);
        assert!(errors.iter().any(|e| e.rule == "missing-command"));
    }

    #[test]
    fn validates_depends_on_exists() {
        let mut config = BivvyConfig::default();
        let step = StepConfig {
            execution: ExecutionConfig {
                command: Some("echo test".to_string()),
                ..Default::default()
            },
            depends_on: vec!["nonexistent".to_string()],
            ..Default::default()
        };
        config.steps.insert("test".to_string(), step);

        let errors = validate_config(&config);
        assert!(errors.iter().any(|e| e.rule == "unknown-step"));
    }

    #[test]
    fn validates_workflow_step_exists() {
        let mut config = BivvyConfig::default();
        let workflow = WorkflowConfig {
            steps: vec!["nonexistent".to_string()],
            ..Default::default()
        };
        config.workflows.insert("default".to_string(), workflow);

        let errors = validate_config(&config);
        assert!(errors.iter().any(|e| e.rule == "unknown-workflow-step"));
    }

    #[test]
    fn detects_circular_dependency() {
        let mut config = BivvyConfig::default();

        let step_a = StepConfig {
            execution: ExecutionConfig {
                command: Some("a".to_string()),
                ..Default::default()
            },
            depends_on: vec!["b".to_string()],
            ..Default::default()
        };

        let step_b = StepConfig {
            execution: ExecutionConfig {
                command: Some("b".to_string()),
                ..Default::default()
            },
            depends_on: vec!["a".to_string()],
            ..Default::default()
        };

        config.steps.insert("a".to_string(), step_a);
        config.steps.insert("b".to_string(), step_b);

        let errors = validate_config(&config);
        assert!(errors.iter().any(|e| e.rule == "circular-dependency"));
    }

    #[test]
    fn valid_config_returns_no_errors() {
        let mut config = BivvyConfig::default();

        let step_a = StepConfig {
            execution: ExecutionConfig {
                command: Some("a".to_string()),
                ..Default::default()
            },
            ..Default::default()
        };

        let step_b = StepConfig {
            execution: ExecutionConfig {
                command: Some("b".to_string()),
                ..Default::default()
            },
            depends_on: vec!["a".to_string()],
            ..Default::default()
        };

        config.steps.insert("a".to_string(), step_a);
        config.steps.insert("b".to_string(), step_b);

        let workflow = WorkflowConfig {
            steps: vec!["a".to_string(), "b".to_string()],
            ..Default::default()
        };
        config.workflows.insert("default".to_string(), workflow);

        let errors = validate_config(&config);
        assert!(errors.is_empty());
    }

    #[test]
    fn validates_workflow_override_in_workflow() {
        let mut config = BivvyConfig::default();

        let step = StepConfig {
            execution: ExecutionConfig {
                command: Some("test".to_string()),
                ..Default::default()
            },
            ..Default::default()
        };
        config.steps.insert("test".to_string(), step);

        let mut overrides = std::collections::HashMap::new();
        overrides.insert("other".to_string(), StepOverride::default());

        let workflow = WorkflowConfig {
            steps: vec!["test".to_string()],
            overrides,
            ..Default::default()
        };
        config.workflows.insert("default".to_string(), workflow);

        let errors = validate_config(&config);
        assert!(errors.iter().any(|e| e.rule == "unknown-override-step"));
    }

    #[test]
    fn validate_returns_result() {
        let config = BivvyConfig::default();
        assert!(validate(&config).is_ok());

        let mut bad_config = BivvyConfig::default();
        bad_config
            .steps
            .insert("empty".to_string(), StepConfig::default());
        assert!(validate(&bad_config).is_err());
    }

